const L=require('fs').readFileSync('/tmp/att.diff','utf8').split('\n');
let minus=[],plus=[],hunk='';
function flush(){
 if(!minus.length&&!plus.length)return;
 const a=minus.join('\n'),b=plus.join('\n');
 // tokenise to words; LCS-free approach: trim common prefix/suffix, then find multiple diffs via simple greedy on words
 const A=a.split(' '),B=b.split(' ');
 let i=0,j=0;const out=[];
 // greedy diff with lookahead
 while(i<A.length||j<B.length){
  if(A[i]===B[j]){i++;j++;continue;}
  // find resync
  let found=false;
  for(let d=1;d<400&&!found;d++){
   for(let x=0;x<=d;x++){const y=d-x;
    if(i+x<A.length&&j+y<B.length&&A[i+x]===B[j+y]&&A[i+x+1]===B[j+y+1]&&A[i+x+2]===B[j+y+2]){
      out.push(`[${hunk}] ctx:"${A.slice(Math.max(0,i-6),i).join(' ')}"\n   - ${A.slice(i,i+x).join(' ')}\n   + ${B.slice(j,j+y).join(' ')}`);
      i+=x;j+=y;found=true;break;}
   }
  }
  if(!found){out.push(`[${hunk}] TAIL - ${A.slice(i).join(' ').slice(0,1500)}\n + ${B.slice(j).join(' ').slice(0,1500)}`);break;}
 }
 console.log(out.join('\n'));console.log('-----');
 minus=[];plus=[];
}
for(const l of L){
 if(l.startsWith('@@')){flush();hunk=l.split(' ')[1];}
 else if(l.startsWith('---')||l.startsWith('+++')||l.startsWith('diff')||l.startsWith('index')||l.startsWith('warning'))continue;
 else if(l.startsWith('-'))minus.push(l.slice(1));
 else if(l.startsWith('+'))plus.push(l.slice(1));
}
flush();
EOF
